protected override async Task ExecuteAsync(CancellationToken stoppingToken)
{
    while (!stoppingToken.IsCancellationRequested)
    {
        try
        {
            var message = await _queue.ReceiveAsync(stoppingToken);
            await ProcessMessageAsync(message, stoppingToken);
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            break; // expected on shutdown
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Message processing failed");
            await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken);
        }
    }
    _logger.LogInformation("OutboxDispatcher stopped gracefully");
}

public sealed class StartupWarmupService : IHostedService
{
    private readonly IServiceScopeFactory _scopes;

    public StartupWarmupService(IServiceScopeFactory scopes) => _scopes = scopes;

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        await using var scope = _scopes.CreateAsyncScope();
        var cache = scope.ServiceProvider.GetRequiredService<ICacheWarmer>();
        await cache.WarmAsync(cancellationToken); // runs once at startup
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

